import{c as i,Z as l,Q as a,j as e,m as u,o as r}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"招魂","description":"","frontmatter":{"title":"招魂","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/8.md","filePath":"books/shici/chuci/8.md"}'),q={name:"books/shici/chuci/8.md"};function p(h,t,n,s,c,d){const o=l("PoemNav");return a(),e("div",null,[t[0]||(t[0]=u('<h1 id="招魂-节选" tabindex="-1">招魂（节选） <a class="header-anchor" href="#招魂-节选" aria-label="Permalink to &quot;招魂（节选）&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>朕幼清以廉洁兮，身服义而未沫。主此盛德兮，牵于俗而芜秽。上无所考此盛德兮，长离殃而愁苦。帝告巫阳曰：&quot;有人在下，我欲辅之。魂魄离散，汝筮予之。&quot;</p><p>巫阳焉乃下招曰：&quot;魂兮归来！去君之恒干，何为四方些？舍君之乐处，而离彼不祥些。&quot;</p><p>&quot;魂兮归来！东方不可以托些。长人千仞，惟魂是索些。十日代出，流金铄石些。彼皆习之，魂往必释些。归来归来！不可以托些。&quot;</p><p>&quot;魂兮归来！南方不可以止些。雕题黑齿，得人肉以祀，以其骨为醢些。蝮蛇蓁蓁，封狐千里些。雄虺九首，往来倏忽，吞人以益其心些。归来归来！不可以久淫些。&quot;</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>招魂：召唤魂魄归来的仪式</li><li>朕：我</li><li>幼清：年少时清白</li><li>服义：践行道义</li><li>未沫：未止</li><li>主：保持</li><li>牵于俗：被世俗牵累</li><li>芜秽：荒芜污秽</li><li>考：考察</li><li>离殃：遭受灾祸</li><li>巫阳：巫师名</li><li>恒干：常住的身体</li><li>些：语气词</li><li>托：依托</li><li>长人：巨人</li><li>仞：古代长度单位</li><li>索：索取</li><li>十日代出：十个太阳轮流出现</li><li>流金铄石：使金铁熔化，石头烧焦</li><li>释：消散</li><li>止：停留</li><li>雕题黑齿：额头上刺花纹、牙齿染黑的人</li><li>醢：肉酱</li><li>蝮蛇：毒蛇</li><li>蓁蓁：众多的样子</li><li>封狐：大狐</li><li>雄虺：大蛇</li><li>倏忽：迅速</li><li>淫：滞留</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>我年少时清白廉洁，亲身践行道义而不止。保持这种盛德，却被世俗牵累而荒芜。上天不考察这种盛德，使我长期遭受灾祸而愁苦。天帝告诉巫阳说：&quot;有人在下方，我想辅佐他。他的魂魄离散，你去占卜召唤回来。&quot;</p><p>巫阳于是下界招魂说：&quot;魂魄啊归来吧！离开你的身体，为什么要去四方呢？舍弃你的乐土，而离开那不祥之地。&quot;</p><p>&quot;魂魄啊归来吧！东方不可以依托。那里有千丈巨人，专门索取魂魄。十个太阳轮流出现，金铁熔化石头烧焦。他们都习惯了，魂魄前去必定消散。归来吧归来吧！不可以依托。&quot;</p><p>&quot;魂魄啊归来吧！南方不可以停留。那里有额上刺花纹、牙齿染黑的人，拿人肉祭祀，把骨头做成肉酱。毒蛇众多，大狐遍布千里。九头大蛇，往来迅速，吞食人来补益它的心。归来吧归来吧！不可以久留。&quot;</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《招魂》是屈原的作品（一说为宋玉所作），是中国文学史上独特的招魂辞。这里节选的是招魂辞的开头部分，描写了召唤魂魄归来的仪式和对四方险恶环境的描述。</p><p>&quot;朕幼清以廉洁兮&quot;，开篇就点明了招魂的对象是一位清白廉洁的君子。&quot;主此盛德兮，牵于俗而芜秽&quot;，写君子虽然品德高尚，却被世俗牵累。&quot;上无所考此盛德兮&quot;，写上天不考察君子的盛德，使他遭受灾祸。</p><p>&quot;帝告巫阳曰&quot;，写天帝命令巫师巫阳去招魂。&quot;魂魄离散，汝筮予之&quot;，点明了招魂的原因。</p><p>&quot;巫阳焉乃下招曰&quot;，写巫阳下界招魂。&quot;魂兮归来&quot;的呼唤，反复出现，形成了强烈的节奏感。</p><p>接着描述四方的险恶。东方有&quot;长人千仞&quot;&quot;十日代出&quot;，南方有&quot;雕题黑齿&quot;&quot;蝮蛇蓁蓁&quot;，这些恐怖的描写，既是为了吓唬魂魄不要离去，也是为了反衬故乡的美好。</p><p>全诗想象奇特，语言瑰丽，将招魂的仪式和神话传说融为一体，是中国浪漫主义文学的独特篇章。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>屈原</strong>（约公元前340年－公元前278年），名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，&quot;楚辞&quot;的创立者和代表作家。代表作有《离骚》《九歌》《天问》等。</p><p><a href="/authors/quyuan.html">查看作者详情 →</a></p></blockquote>',24)),r(o)])}const b=i(q,[["render",p]]);export{m as __pageData,b as default};
